using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var modelName = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.Error.WriteLine("Error: Set the OPENAI_API_KEY environment variable.");
    return 1;
}

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var notepad = new Notepad();

var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearchTool.SearchAsync),
    AIFunctionFactory.Create(WebSearchTool.FetchPageAsync),
    AIFunctionFactory.Create(notepad.AddNote),
    AIFunctionFactory.Create(notepad.GetNotes),
};

// ---------------------------------------------------------------------------
// Chat client pipeline (OpenAI → function-invoking middleware)
// ---------------------------------------------------------------------------
IChatClient innerClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelName)
    .AsIChatClient();

IChatClient chatClient = new ChatClientBuilder(innerClient)
    .UseFunctionInvocation()
    .Build();

// ---------------------------------------------------------------------------
// Agent
// ---------------------------------------------------------------------------
var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    description: "An AI research assistant that searches the web, takes notes, and summarizes findings.",
    instructions: """
        You are a thorough research agent. When given a topic:
        1. Use the SearchAsync tool to find relevant web results.
        2. Use FetchPageAsync to read promising pages for deeper detail.
        3. Use AddNote to record key facts, statistics, and source URLs.
        4. When you have gathered enough information, use GetNotes to review
           everything, then produce a well-structured summary with citations.
        Be concise but comprehensive. Always cite your sources.
        """,
    tools: tools);

// ---------------------------------------------------------------------------
// Interactive loop
// ---------------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        🔍  Research Agent  (v1.0)       ║");
Console.WriteLine("║  Type a topic to research, or 'quit'.   ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notepad.Clear();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a detailed summary: {topic}"),
    };

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("\n⏳ Researching…\n");
    Console.ResetColor();

    var session = await agent.CreateSessionAsync();
    var response = await agent.RunAsync(messages, session);

    Console.ForegroundColor = ConsoleColor.Green;
    Console.WriteLine("── Research Summary ──────────────────────");
    Console.ResetColor();
    Console.WriteLine(response.Text);
    Console.WriteLine();
}

return 0;

// ═══════════════════════════════════════════════════════════════════════════
// Tool implementations
// ═══════════════════════════════════════════════════════════════════════════

/// <summary>Provides web search and page-fetching capabilities.</summary>
static class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html,application/xhtml+xml" },
        },
    };

    [Description("Searches the web for information on a query and returns a list of result titles, snippets, and URLs.")]
    public static async Task<string> SearchAsync(
        [Description("The search query")] string query)
    {
        // Use DuckDuckGo Instant Answer API (free, no key required)
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

        try
        {
            using var doc = await Http.GetFromJsonAsync<JsonDocument>(url);
            var results = new List<string>();

            // Abstract / main answer
            var abstractText = doc?.RootElement.GetProperty("AbstractText").GetString();
            var abstractUrl = doc?.RootElement.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
                results.Add($"[Abstract] {abstractText}\n  URL: {abstractUrl}");

            // Related topics
            if (doc?.RootElement.TryGetProperty("RelatedTopics", out var related) == true)
            {
                foreach (var item in related.EnumerateArray().Take(8))
                {
                    var text = item.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var link = item.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                        results.Add($"• {text}\n  URL: {link}");
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : "No results found. Try a different or more specific query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try rephrasing the query.";
        }
    }

    [Description("Fetches and extracts the text content of a web page given its URL. Use this to get deeper information from a search result.")]
    public static async Task<string> FetchPageAsync(
        [Description("The full URL of the page to fetch")] string url)
    {
        try
        {
            var html = await Http.GetStringAsync(url);

            // Lightweight HTML-to-text: strip tags and compress whitespace
            var text = System.Text.RegularExpressions.Regex.Replace(html, "<script[^>]*>[\\s\\S]*?</script>", " ");
            text = System.Text.RegularExpressions.Regex.Replace(text, "<style[^>]*>[\\s\\S]*?</style>", " ");
            text = System.Text.RegularExpressions.Regex.Replace(text, "<[^>]+>", " ");
            text = System.Text.Html.HtmlDecode(text) ?? text;
            text = System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ").Trim();

            // Limit to ~4000 chars to stay within context limits
            return text.Length > 4000 ? text[..4000] + "… [truncated]" : text;
        }
        catch (Exception ex)
        {
            return $"Failed to fetch page: {ex.Message}";
        }
    }
}

/// <summary>A simple in-memory notepad the agent uses to record research findings.</summary>
sealed class Notepad
{
    private readonly List<string> _notes = [];

    [Description("Adds a research note. Use this to record key facts, quotes, or source URLs discovered during research.")]
    public string AddNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Retrieves all saved research notes so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes recorded yet.";

        return string.Join("\n", _notes.Select((n, i) => $"[{i + 1}] {n}"));
    }

    public void Clear() => _notes.Clear();
}

