 using System.ComponentModel;
 using System.Net.Http.Json;
 using System.Text.Json;
 using Microsoft.Extensions.AI;
 using Microsoft.Agents.AI;

 // ---------------------------------------------------------------------------
 // Configuration
 // ---------------------------------------------------------------------------
 var modelName = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
 if (string.IsNullOrWhiteSpace(apiKey))
 {
     Console.Error.WriteLine("Error: Set the OPENAI_API_KEY environment variable.");
     return 1;
 }

 // ---------------------------------------------------------------------------
 // Tools
 // ---------------------------------------------------------------------------
 var notepad = new Notepad();

 var tools = new AITool[]
 {
     AIFunctionFactory.Create(WebSearchTool.SearchAsync),
     AIFunctionFactory.Create(WebSearchTool.FetchPageAsync),
     AIFunctionFactory.Create(notepad.AddNote),
     AIFunctionFactory.Create(notepad.GetNotes),
 };

 // ---------------------------------------------------------------------------
 // Chat client pipeline (OpenAI → function-invoking middleware)
 // ---------------------------------------------------------------------------
 IChatClient innerClient = new OpenAI.OpenAIClient(apiKey)
     .GetChatClient(modelName)
     .AsIChatClient();

 IChatClient chatClient = new ChatClientBuilder(innerClient)
     .UseFunctionInvocation()
     .Build();

 // ---------------------------------------------------------------------------
 // Agent
 // ---------------------------------------------------------------------------
 var agent = new ChatClientAgent(
     chatClient,
     name: "ResearchAgent",
     description: "An AI research assistant that searches the web, takes notes, and summarizes findings.",
     instructions: """
         You are a thorough research agent. When given a topic:
         1. Use the SearchAsync tool to find relevant web results.
         2. Use FetchPageAsync to read promising pages for deeper detail.
         3. Use AddNote to record key facts, statistics, and source URLs.
         4. When you have gathered enough information, use GetNotes to review
            everything, then produce a well-structured summary with citations.
         Be concise but comprehensive. Always cite your sources.
         """,
     tools: tools);

 // ---------------------------------------------------------------------------
 // Interactive loop
 // ---------------------------------------------------------------------------
 Console.WriteLine("╔══════════════════════════════════════════╗");
 Console.WriteLine("║        🔍  Research Agent  (v1.0)       ║");
 Console.WriteLine("║  Type a topic to research, or 'quit'.   ║");
 Console.WriteLine("╚══════════════════════════════════════════╝");
 Console.WriteLine();

 while (true)
 {
     Console.ForegroundColor = ConsoleColor.Cyan;
     Console.Write("Research topic> ");
     Console.ResetColor();

     var topic = Console.ReadLine()?.Trim();
     if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
         break;

     notepad.Clear();

     var messages = new List<ChatMessage>
     {
         new(ChatRole.User, $"Research the following topic and provide a detailed summary: {topic}"),
     };

     Console.ForegroundColor = ConsoleColor.DarkGray;
     Console.WriteLine("\n⏳ Researching…\n");
     Console.ResetColor();

     var session = await agent.CreateSessionAsync();
     var response = await agent.RunAsync(messages, session);

     Console.ForegroundColor = ConsoleColor.Green;
     Console.WriteLine("── Research Summary ──────────────────────");
     Console.ResetColor();
     Console.WriteLine(response.Text);
     Console.WriteLine();
 }

 return 0;

