         }
     }

     [Description("Fetches and extracts the text content of a web page given its URL. Use this to get deeper information from a search result.")]
     public static async Task<string> FetchPageAsync(
         [Description("The full URL of the page to fetch")] string url)
     {
         try
         {
             var html = await Http.GetStringAsync(url);

             // Lightweight HTML-to-text: strip tags and compress whitespace
             var text = System.Text.RegularExpressions.Regex.Replace(html, "<script[^>]*>[\\s\\S]*?</script>", " ");
             text = System.Text.RegularExpressions.Regex.Replace(text, "<style[^>]*>[\\s\\S]*?</style>", " ");
             text = System.Text.RegularExpressions.Regex.Replace(text, "<[^>]+>", " ");
             text = System.Net.WebUtility.HtmlDecode(text) ?? text;
             text = System.Text.RegularExpressions.Regex.Replace(text, @"\s+", " ").Trim();

             // Limit to ~4000 chars to stay within context limits
             return text.Length > 4000 ? text[..4000] + "… [truncated]" : text;
         }
         catch (Exception ex)
         {
             return $"Failed to fetch page: {ex.Message}";
         }
     }
 }

 /// <summary>A simple in-memory notepad the agent uses to record research findings.</summary>
 sealed class Notepad
 {
     private readonly List<string> _notes = [];

     [Description("Adds a research note. Use this to record key facts, quotes, or source URLs discovered during research.")]
     public string AddNote(
         [Description("The note content to save")] string note)
     {
         _notes.Add(note);
         return $"Note #{_notes.Count} saved.";
     }

     [Description("Retrieves all saved research notes so far.")]
     public string GetNotes()
     {
         if (_notes.Count == 0)
             return "No notes recorded yet.";

         return string.Join("\n", _notes.Select((n, i) => $"[{i + 1}] {n}"));
     }

     public void Clear() => _notes.Clear();
 }
